$rows=['Harga'=>'price','Tier'=>'tier','Kondisi'=>'condition_type','Kategori'=>'category_type','Brand'=>'brand','Prosesor'=>'processor','Grafis'=>'gpu','RAM'=>'ram_gb','Penyimpanan'=>'storage_gb','Jenis penyimpanan'=>'storage_type','Layar'=>'display_size','Bobot'=>'weight_kg','Kebutuhan'=>'use_cases'];
